export function getGuideBySlugEn(slug: string): MoroccoGuideEn | undefined {
    return MOROCCO_GUIDES_EN.find((g) => g.slug === slug);
}

export function getAllGuideSlugsEn(): string[] {
    return MOROCCO_GUIDES_EN.map((g) => g.slug);
}

export const getGuideEnBySlug = getGuideBySlugEn;
